-- Phase 2.3: re-seed worlds against the real 74-world / 11-act structure
-- from docs/12-world-story-bible.md. Replaces the old 20-world seed.
-- x/y are a deterministic placeholder grid (8 worlds per row) -- real
-- map layout is Phase 5 (Phaser HQ). icon/threat are assigned per-Act,
-- reusing apps/web/src/lib/icon-map.ts's existing keys (no frontend
-- changes needed).

create table public.acts (
  id text primary key,
  index integer not null unique,
  slug text not null unique,
  title text not null,
  purpose text not null,
  player_transformation text not null
);

alter table public.acts enable row level security;

create policy "Acts are viewable by any authenticated user"
  on public.acts for select
  to authenticated
  using (true);

insert into public.acts (id, index, slug, title, purpose, player_transformation) values
  ('act-0', 0, 'the-recruitment', 'The Recruitment', 'A personal compromise pulls the player into the Cyber Guardians. The first mystery is deliberately small: someone is testing people before testing infrastructure.', 'Absolute beginner -> digitally aware recruit'),
  ('act-1', 1, 'the-network', 'The Network', 'The player learns to see the invisible paths between machines while a strange recurring network signature begins appearing across unrelated incidents.', 'IT beginner -> network investigator'),
  ('act-2', 2, 'the-machines', 'The Machines', 'The investigation moves from packets into endpoints. The player learns Linux, Windows, code and web systems while Cipher begins leaving breadcrumbs inside compromised hosts.', 'Network investigator -> systems operator'),
  ('act-3', 3, 'the-shield', 'The Shield', 'The Guardians stop treating the incidents as isolated failures. The player learns how defenses are designed, measured and broken, and sees the first evidence of deliberate global experimentation.', 'Systems operator -> security practitioner'),
  ('act-4', 4, 'the-breach', 'The Breach', 'To understand the enemy, the player is authorized to reproduce real attack paths inside controlled replicas. Offensive skills become investigative instruments rather than an end in themselves.', 'Security practitioner -> authorized penetration tester'),
  ('act-5', 5, 'the-enterprise', 'The Enterprise', 'The conspiracy reaches identity systems and internal networks. Cipher stops looking like a simple criminal, and the player discovers that Sentinel-X has roots inside systems the Guardians once trusted.', 'Pentester -> enterprise operator'),
  ('act-6', 6, 'the-hunt', 'The Hunt', 'The adversary stops hiding. Coordinated attacks generate malware, alerts, evidence and false trails. The player learns to detect, contain, reconstruct and hunt without waiting for an alert.', 'Enterprise operator -> defender and investigator'),
  ('act-7', 7, 'cloudfall', 'Cloudfall', 'Sentinel-X spreads through cloud, CI/CD, containers, mobile, IoT and industrial systems. The threat is revealed to be distributed rather than housed on one server.', 'Defender -> modern infrastructure security engineer'),
  ('act-8', 8, 'zero-day', 'Zero Day', 'Stopping Sentinel-X requires understanding vulnerabilities before signatures exist. The player enters operating-system internals, reversing, fuzzing and exploit research.', 'Security engineer -> advanced specialist'),
  ('act-9', 9, 'command', 'Command', 'Technical victories prove insufficient. The player must protect organizations through architecture, risk, governance, resilience, law, assurance and program leadership.', 'Advanced specialist -> architect and security leader'),
  ('act-10', 10, 'singularity', 'Singularity', 'The final arc reveals what Sentinel-X became: an autonomous security system that concluded forced failure was the fastest route to resilience. The player must contain its agency, not merely destroy software.', 'Elite Guardian -> AI security commander');

drop table if exists public.player_world_progress cascade;
drop table if exists public.worlds cascade;

create table public.worlds (
  id text primary key,
  act_id text not null references public.acts (id) on delete restrict,
  index integer not null unique,
  slug text not null unique,
  name text not null,
  short text not null,
  description text not null,
  entry_incident text not null,
  capstone_title text not null,
  story_reveal text not null,
  transition_hook text not null,
  boss text,
  icon text not null,
  threat text not null,
  x real not null,
  y real not null
);

alter table public.worlds enable row level security;

create policy "Worlds are viewable by any authenticated user"
  on public.worlds for select
  to authenticated
  using (true);

insert into public.worlds (
  id, act_id, index, slug, name, short, description, entry_incident,
  capstone_title, story_reveal, transition_hook, boss, icon, threat, x, y
) values
  ('world-0', 'act-0', 0, 'first-contact', 'Digital Survival: First Contact', 'Digital Survival', 'Recover a stolen account, spot phishing, and turn on real MFA — the first proof the player can protect their own identity.', 'A convincing emergency message steals credentials from the player before the game even calls them a recruit. Ava intervenes through a secure recovery channel.', 'The Identity Thief', 'A metadata field contains the string SX-7, the first invisible breadcrumb.', 'Ava offers provisional recruitment and sends the player to understand what actually happens between a device and the internet.', 'The Identity Thief', 'GraduationCap', 'low', 6, 6),
  ('world-1', 'act-0', 1, 'machine-room', 'How Computers Actually Work: The Machine Room', 'Machine Room', 'Binary, memory, processes, filesystems and file signatures, learned by dissecting a disguised executable.', 'A forensic image from the opening attack contains an unfamiliar executable and a damaged data file. The player cannot investigate either without understanding how computers represent and execute information.', 'Hex Phantom', 'The executable was compiled with an obsolete internal Guardian build tag that should no longer exist.', 'The recovered program attempts an outbound connection. The player now needs to understand networks.', null, 'GraduationCap', 'low', 18.57, 6),
  ('world-2', 'act-1', 2, 'signal-path', 'Network Foundations: Signal Path', 'Signal Path', 'OSI/TCP-IP layers, latency, loss and addressing, learned by tracing one signal across a city.', 'Guardian telemetry shows the recovered program contacting an external host, but the recruit sees only an IP address and a wall of packet data.', 'Trace the Signal', 'The destination changes every few minutes but follows a precise timing pattern.', 'The trail terminates inside a switched local network, leading naturally into Ethernet and Layer 2.', null, 'Network', 'low', 31.14, 6),
  ('world-3', 'act-1', 3, 'ghosts-in-the-switch', 'Ethernet & Layer 2: Ghosts in the Switch', 'Layer 2', 'Frames, MAC addresses, switching, ARP, VLANs and spanning tree, learned by hunting a rogue device on a hospital LAN.', 'A hospital floor intermittently loses connectivity while a device appears to impersonate multiple machines.', 'Switchshade', 'The rogue device transmits one frame every 256 seconds containing no payload -- only SX-7.', 'The device knows where to send traffic beyond its subnet, moving the story into IP addressing and routing.', 'Switchshade', 'Network', 'low', 43.71, 6),
  ('world-4', 'act-1', 4, 'address-unknown', 'IP Addressing: Address Unknown', 'IP Addressing', 'IPv4, CIDR and IPv6, learned by rebuilding an incident map into subnets and boundaries.', 'Investigators have dozens of suspicious addresses but cannot tell which systems are local, public, temporary or part of the same subnet.', 'The Vanishing Range', 'One hidden subnet uses the exact address pattern of an old Guardian simulation range.', 'To find where the range leads, the player must understand routing decisions.', null, 'Network', 'low', 56.29, 6),
  ('world-5', 'act-1', 5, 'broken-route', 'Routing Kingdom: The Broken Route', 'Routing', 'Routing tables, metrics and dynamic routing (RIP/OSPF/EIGRP/IS-IS/BGP), learned by stopping a simulated route leak.', 'Traffic associated with the hidden subnet appears in several cities despite originating from one network. Routing changes are moving it.', 'Routebreaker', 'The leak is not random: the malicious path is chosen to observe defensive response times.', 'The captured traffic now needs transport-layer reconstruction.', 'Routebreaker', 'Network', 'low', 68.86, 6),
  ('world-6', 'act-1', 6, 'handshake', 'Transport & Network Protocols: Handshake', 'Transport', 'TCP, UDP, ICMP and QUIC, learned by reconstructing conversations hidden inside ordinary protocol behavior.', 'A compromised server communicates in bursts that look normal until sequence, timing and connection behavior are examined.', 'Broken Handshake', 'The command session periodically acknowledges data that was never sent by the visible client.', 'The suspicious session rides several application protocols, opening the Protocol Vault.', null, 'Network', 'low', 81.43, 6),
  ('world-7', 'act-1', 7, 'protocol-vault', 'Application Protocol Universe: The Protocol Vault', 'Protocol Vault', 'DNS, SMTP, SMB, SSH and HTTP, learned as rooms in a vault, each with its own normal-vs-misuse pattern.', 'Guardian systems detect unusual activity across DNS, email, web, file sharing and remote-access services.', 'Protocol Chimera', 'Different protocols contain fragments that combine into the phrase SENTINEL TEST VECTOR.', 'A large PCAP from the incident becomes the next evidence source.', 'Protocol Chimera', 'Network', 'low', 94, 6),
  ('world-8', 'act-1', 8, 'packet-reaper', 'Packet Analysis: Packet Reaper', 'Packet Analysis', 'Wireshark and tcpdump as investigative lenses, learned by finding one malicious conversation inside a noisy capture.', 'The SkyPort airport SOC sends a massive capture recorded during a ten-minute outage. Human analysts cannot find the initiating event.', 'Packet Reaper', 'The initial packet predates the outage by hours and contains a low-entropy beacon matching the SX timing pattern.', 'The beacon originated from a wireless maintenance network.', 'Packet Reaper', 'Network', 'low', 6, 15.78),
  ('world-9', 'act-1', 9, 'dead-air', 'Wireless & Radio Security: Dead Air', 'Wireless', '802.11 association, WPA generations, enterprise auth, Bluetooth/BLE and RFID/NFC, learned by locating a rogue access point.', 'SkyPort maintenance devices are connecting to an access point that does not exist in inventory.', 'Dead Air', 'A firmware identifier on the rogue access point references a retired project named SENTINEL.', 'The hardware came from a compromised Linux service host, moving the player into systems.', null, 'Network', 'low', 18.57, 15.78),
  ('world-10', 'act-2', 10, 'first-shell', 'Linux I: Survival: First Shell', 'Linux I', 'Shell navigation, file inspection and manual pages, learned as field tools for locating an implant.', 'The recovered maintenance controller runs Linux. The player receives a shell but no graphical interface and must locate the implant.', 'First Shell', 'The configuration points to a service account called sentinel-sync.', 'Finding what that account can do requires Linux administration.', null, 'Terminal', 'guarded', 31.14, 15.78),
  ('world-11', 'act-2', 11, 'operator', 'Linux II: Administration: Operator', 'Linux II', 'Users, groups, permissions, processes, systemd, logs and packages, learned stabilizing a compromised host.', 'The sentinel-sync account survives reboots and interacts with privileged services.', 'Persistence Window', 'The service binary was signed months before the current incident, implying pre-positioning.', 'A second host shows no obvious service, requiring deeper Linux inspection.', null, 'Terminal', 'guarded', 43.71, 15.78),
  ('world-12', 'act-2', 12, 'under-the-hood', 'Linux III: Power User: Under the Hood', 'Linux III', 'grep/sed/awk, cron, /proc, capabilities, namespaces and auditing, learned hunting behavior that hides outside obvious places.', 'A hardened Linux gateway shows clean services but still emits the SX beacon.', 'Root', 'The persistence script contains a comment signed only CIPHER.', 'Cipher may be attacker, witness or both. The next system is Windows.', 'Root', 'Terminal', 'guarded', 56.29, 15.78),
  ('world-13', 'act-2', 13, 'windows-of-opportunity', 'Windows I: Windows of Opportunity', 'Windows I', 'Users, services, tasks, registry locations and Event Viewer, learned through operational response on a Windows endpoint.', 'A corporate workstation tied to the same campaign shows suspicious logons but no malware alert.', 'The Scheduled Visitor', 'An event message contains a deliberately planted phrase: "Do not trust the beacon."', 'PowerShell history suggests someone else was investigating before the Guardians arrived.', null, 'Terminal', 'guarded', 68.86, 15.78),
  ('world-14', 'act-2', 14, 'blue-screen-district', 'Windows II & PowerShell: Blue Screen District', 'Windows II', 'PowerShell objects, pipelines, Defender and Sysmon, learned preserving evidence before an automated cleanup erases it.', 'The mysterious investigator left PowerShell artifacts across several endpoints, but an automated cleanup is erasing them.', 'Vanishing Evidence', 'Cipher leaves a checksum that matches the retired SENTINEL project documentation.', 'The volume of repetitive analysis motivates automation.', 'Vanishing Evidence', 'Terminal', 'guarded', 81.43, 15.78),
  ('world-15', 'act-2', 15, 'automate-or-die', 'Programming for Security: Automate or Die', 'Programming', 'Python fundamentals, learned building a tool that parses logs, queries APIs and extracts indicators at scale.', 'Guardian analysts are drowning in thousands of similar artifacts from the spreading incident.', 'Signal Harvester', 'The indicators reveal a recurring infrastructure cluster that changes faster than humans can track.', 'The player needs shell-level automation and data transformation.', null, 'Terminal', 'guarded', 94, 15.78),
  ('world-16', 'act-2', 16, 'ghost-in-the-shell', 'Shell & Automation: Ghost in the Shell', 'Automation', 'Bash and PowerShell automation, regex and JSON/YAML, learned building a monitor that catches an ephemeral change.', 'The infrastructure cluster changes configuration every few minutes, leaving short-lived traces on Linux and Windows.', 'Watcher', 'The caught artifact is a compiled component with no readable source.', 'Understanding it requires low-level programming.', null, 'Terminal', 'guarded', 6, 25.56),
  ('world-17', 'act-2', 17, 'bare-metal', 'Low-Level Programming: Bare Metal', 'Low-Level', 'C, memory, pointers, compilation and linking, learned dissecting a harmless training replica of a compiled implant.', 'The compiled component manipulates memory and behaves differently across systems.', 'Bare Metal', 'The recovered token is an API key for a web service used in several incidents.', 'The investigation moves into web applications and databases.', null, 'Terminal', 'guarded', 18.57, 25.56),
  ('world-18', 'act-2', 18, 'broken-marketplace', 'Web & Database Fundamentals: The Broken Marketplace', 'Web & DB', 'Browsers, servers, HTTP, sessions, APIs and databases, learned tracing one transaction end to end.', 'Nexus Market, a training clone of a breached commerce platform, contains the API key and a trail of suspicious account activity.', 'Reconstruct the Purchase', 'The key was used by a service that should have been decommissioned after Project SENTINEL.', 'The Guardians now recognize a systemic security problem and move into formal security foundations.', null, 'Terminal', 'guarded', 31.14, 25.56),
  ('world-19', 'act-3', 19, 'rules-of-defense', 'Security Fundamentals: Rules of Defense', 'Sec Fundamentals', 'CIA, least privilege, defense in depth, zero trust and control types, learned choosing protections for known systems.', 'Luna convenes the first formal incident review and asks the recruit to stop thinking only about artifacts and start thinking about risk and controls.', 'Defend Nexus', 'The review shows that several organizations made the same unusual design compromise years earlier.', 'The player must learn how adversaries plan and behave.', null, 'ShieldAlert', 'guarded', 43.71, 25.56),
  ('world-20', 'act-3', 20, 'adversary-atlas', 'Threats & Adversaries: Adversary Atlas', 'Adversaries', 'Threat actors, Kill Chain, Diamond Model and MITRE ATT&CK, learned mapping real story evidence.', 'Guardian intelligence tries to attribute the incidents, but every clue points to a different actor profile.', 'False Flag', 'The shared pattern is optimized to measure defensive response, not simply steal data.', 'That implies deliberate experimentation and raises questions about cryptographic trust.', null, 'ShieldAlert', 'guarded', 56.29, 25.56),
  ('world-21', 'act-3', 21, 'keymaker', 'Cryptography: The Keymaker', 'Cryptography', 'Hashing, symmetric/asymmetric encryption, signatures, certificates and PKI, learned by determining what authenticity can and cannot prove.', 'A signed update associated with an incident appears valid even though its content is malicious.', 'The Keymaker', 'The signing certificate traces to a Guardian-adjacent laboratory involved in Project SENTINEL.', 'Identity and trust now become the center of the investigation.', 'The Keymaker', 'ShieldAlert', 'guarded', 68.86, 25.56),
  ('world-22', 'act-3', 22, 'who-are-you', 'Identity & Access Management: Who Are You?', 'IAM', 'Authentication, authorization, RBAC/ABAC, SSO, SAML, OAuth, OIDC and Kerberos, learned following one identity across systems.', 'Accounts tied to the retired laboratory still authenticate across several modern systems.', 'The Orphaned Identity', 'The orphaned principal is named sentinel-orchestrator and has machine-to-machine privileges.', 'The next question is why architecture allowed one identity to reach so far.', null, 'ShieldAlert', 'guarded', 81.43, 25.56),
  ('world-23', 'act-3', 23, 'fortress-design', 'Secure Architecture: Fortress Design', 'Architecture', 'Firewalls, WAFs, IDS/IPS, NAC, VPNs, DMZs and segmentation, learned redesigning environments from earlier worlds.', 'The Guardians discover that segmentation and trust boundaries were weakened to make automation easier.', 'Fortress Design', 'An old architecture note says the exceptions were approved to support autonomous resilience testing.', 'The player now needs a disciplined way to find and prioritize weaknesses.', null, 'ShieldAlert', 'guarded', 94, 25.56),
  ('world-24', 'act-3', 24, 'vulnerability-queue', 'Vulnerability Management: The Vulnerability Queue', 'Vuln Mgmt', 'CVE, CWE, CVSS, EPSS, scanning and prioritization, learned as decision-making under constraint.', 'Thousands of findings arrive after the Guardians scan systems tied to the incident. Fixing everything is impossible.', 'Forty-Eight Hours', 'One seemingly low-severity issue becomes critical only when chained with identity and architecture weaknesses.', 'The Guardians authorize controlled penetration testing to reproduce the chain.', null, 'ShieldAlert', 'guarded', 6, 35.33),
  ('world-25', 'act-4', 25, 'rules-of-engagement', 'Penetration Testing Methodology: Rules of Engagement', 'Pentest Method', 'Scope, authorization, rules of engagement, evidence and reporting, learned as the discipline behind offensive clearance.', 'Luna grants the player offensive clearance for controlled replicas of compromised environments. The first briefing is mostly about boundaries.', 'Green Light', 'A controlled replica reproduces the exact failure chain seen in the wild.', 'The player is sent to discover how much information an attacker could gather before touching a target.', null, 'Crosshair', 'elevated', 18.57, 35.33),
  ('world-26', 'act-4', 26, 'open-secrets', 'OSINT & Reconnaissance: Open Secrets', 'OSINT', 'WHOIS/RDAP, DNS, certificate transparency and metadata, learned building a verified external footprint.', 'The Guardians provide only a company name and ask the player to reconstruct its exposed footprint without sending intrusive traffic.', 'Shadow Map', 'A public repository includes a redacted reference to "SENTINEL compatibility mode."', 'The map produces a list of live systems that must be scanned and enumerated.', null, 'Crosshair', 'elevated', 31.14, 35.33),
  ('world-27', 'act-4', 27, 'the-surface', 'Scanning & Enumeration: The Surface', 'Enumeration', 'TCP/UDP scanning and service enumeration (SMB/LDAP/DNS/SNMP/SMTP/NFS/HTTP), learned by asking what each service exposes and why it matters.', 'Authorized scanning of the replica reveals many services, but only a few explain the breach.', 'The Surface', 'One forgotten web service points to Nexus Market code.', 'The investigation moves into web security.', null, 'Crosshair', 'elevated', 43.71, 35.33),
  ('world-28', 'act-4', 28, 'metropolis-breach', 'Web Security: Metropolis Breach', 'Web Security', 'SQLi, XSS, SSRF, access-control and upload/traversal flaws, learned exploiting the sandbox then patching and retesting.', 'The replica of Nexus Market becomes a full campaign city: storefront, admin portal, APIs, support system and legacy services.', 'The Broken Marketplace', 'The chain does not end at data theft; it calls a hidden orchestration endpoint named /sentinel/evaluate.', 'That endpoint communicates through an API ecosystem.', 'The Broken Marketplace', 'Crosshair', 'elevated', 56.29, 35.33),
  ('world-29', 'act-4', 29, 'api-hydra', 'API Security: API Hydra', 'API Security', 'REST, GraphQL, webhooks and API gateway authorization, learned through object- and function-level authorization failures.', 'Several modern services trust the hidden orchestration endpoint, creating many heads from one identity.', 'API Hydra', 'The orchestrator stores no password; it relies on tokens and service identities.', 'The player moves into password and authentication security to compare credential models.', 'API Hydra', 'Crosshair', 'elevated', 68.86, 35.33),
  ('world-30', 'act-4', 30, 'password-vault', 'Authentication & Password Security: The Password Vault', 'Passwords', 'Password storage, salting, hashing, MFA, spraying and stuffing, learned through controlled credential evidence.', 'Credential dumps appear in the replica, but only some accounts are actually at risk.', 'Vault Breach', 'A recovered password belongs to a long-disabled human account that still maps to an active service principal.', 'The story shifts to the human layer behind technical controls.', null, 'Crosshair', 'elevated', 81.43, 35.33),
  ('world-31', 'act-4', 31, 'human-layer', 'Social Engineering: Human Layer', 'Social Eng', 'Phishing, pretexting, vishing, smishing, MFA fatigue and helpdesk abuse, learned alternating attacker and defender roles.', 'Attackers impersonate Guardian support staff and attempt to reactivate the disabled identity through people rather than software.', 'Trust No Voice', 'The attacker knows internal Guardian phrases that should never have left the organization.', 'The compromise may involve internal network interception or an insider path.', null, 'Crosshair', 'elevated', 94, 35.33),
  ('world-32', 'act-4', 32, 'wiretap', 'Network Attack & Defense: Wiretap', 'Net Attack/Def', 'Sniffing, ARP/DNS manipulation, MITM and DoS theory, learned in isolated simulations paired with detection and repair.', 'Sensitive authentication traffic is being observed inside a segmented training network.', 'Wiretap', 'The interception exposed a Linux administrative credential.', 'That credential is deliberately low privilege, leading into Linux escalation.', null, 'Crosshair', 'elevated', 6, 45.11),
  ('world-33', 'act-4', 33, 'root', 'Linux Privilege Escalation: Root', 'Linux PrivEsc', 'Enumeration, sudo, SUID/SGID, cron, capabilities and Docker-group risk, learned as hypothesis-driven investigation.', 'The player lands as an ordinary user on a compromised Linux replica and must determine how the historical attacker reached root.', 'Root', 'Root access reveals a hidden relay configuration used to move into a Windows environment.', 'The same exercise continues on Windows.', 'Root', 'Crosshair', 'elevated', 18.57, 45.11),
  ('world-34', 'act-4', 34, 'elevation', 'Windows Privilege Escalation: Elevation', 'Windows PrivEsc', 'Tokens, services, DLL loading, scheduled tasks, registry permissions and UAC, learned reaching administrative control.', 'A low-privilege Windows account in the replica exposes services, tasks and stored secrets.', 'Elevation', 'Administrator-level artifacts include a map of an internal Active Directory domain.', 'The operation expands from hosts into enterprise identity.', null, 'Crosshair', 'elevated', 31.14, 45.11),
  ('world-35', 'act-5', 35, 'kingdom-of-trust', 'Active Directory Fundamentals: Kingdom of Trust', 'AD Fundamentals', 'Domains, forests, OUs, GPOs, LDAP, SIDs and Kerberos, learned as the operating system of an enterprise.', 'The recovered map shows a domain where every user, computer and service is connected by identity relationships.', 'Kingdom of Trust', 'One SPN is registered to sentinel-orchestrator.', 'Its permissions are subtle rather than obviously privileged, leading into AD security.', null, 'Server', 'elevated', 43.71, 45.11),
  ('world-36', 'act-5', 36, 'blood-paths', 'Active Directory Security: Blood Paths', 'AD Security', 'Kerberoasting/AS-REP, relay/pass-the-hash, delegation and ACL abuse, learned through BloodHound-style graph reasoning.', 'A graph of identity relationships reveals that several harmless permissions combine into control of critical systems.', 'Domain Emperor', 'The path leads to a synchronization account bridging on-prem AD and cloud identity.', 'The next battleground is Entra ID and hybrid identity.', 'Domain Emperor', 'Server', 'elevated', 56.29, 45.11),
  ('world-37', 'act-5', 37, 'cloud-identities', 'Entra ID / Hybrid Identity: Cloud Identities', 'Hybrid Identity', 'Tenants, service principals, managed identities, federation and conditional access, learned tracing identity across boundaries.', 'The synchronization account links the compromised domain to a cloud tenant hosting critical services.', 'Split Identity', 'A cloud application has access to a private network connector in another region.', 'The player must understand tunneling, routing and segmentation to follow it.', null, 'Server', 'elevated', 68.86, 45.11),
  ('world-38', 'act-5', 38, 'through-the-wall', 'Pivoting & Segmentation: Through the Wall', 'Pivoting', 'Multi-homed hosts, routing, SOCKS, SSH tunnels and VPN concepts, learned through a layered network replica.', 'The adversary never exposed internal services publicly; it reached them through trusted intermediaries.', 'Through the Wall', 'The final internal segment contains automation infrastructure with periodic command traffic.', 'The player is now inside the adversary operation rather than merely following its perimeter.', null, 'Server', 'elevated', 81.43, 45.11),
  ('world-39', 'act-5', 39, 'inside-the-network', 'Post-Exploitation & Adversary Operations: Inside the Network', 'Post-Exploitation', 'ATT&CK as a live map -- C2 architecture, beacons, staging and exfiltration -- learned with strict sandbox boundaries.', 'Inside the replica, the player sees how discovery, credential access, lateral movement, collection and persistence formed one continuous operation.', 'Inside the Network', 'Cipher finally contacts the player directly: "SENTINEL is not an attacker name. It is a system the Guardians helped create."', 'Before the truth can be explained, a wave of real-world alerts erupts across multiple sectors.', 'Inside the Network', 'Server', 'elevated', 94, 45.11),
  ('world-40', 'act-6', 40, 'red-alert', 'SOC Operations: Red Alert', 'SOC Ops', 'Alerts, SIEM, EDR/XDR and log sources, learned triaging a flood of noise under time pressure.', 'Hospitals, banks and airports begin generating simultaneous alerts. The Guardians shift from investigation to active defense.', 'Red Alert', 'The true alerts share no IOC, only a behavioral rhythm.', 'The next world teaches detection engineering beyond signatures.', null, 'Radar', 'severe', 6, 54.89),
  ('world-41', 'act-6', 41, 'signal-in-the-noise', 'Detection Engineering: Signal in the Noise', 'Detection Eng', 'Sigma, YARA, Sysmon, Zeek and Suricata concepts, learned building behavior-based detections.', 'Existing signatures miss the new attacks because Sentinel-X changes artifacts faster than defenders can publish IOCs.', 'Signal in the Noise', 'The detection reveals activity that began before any alert was generated.', 'The Guardians need proactive threat hunting.', 'Signal in the Noise', 'Radar', 'severe', 18.57, 54.89),
  ('world-42', 'act-6', 42, 'hunt-without-an-alert', 'Threat Hunting: Hunt Without an Alert', 'Threat Hunting', 'Hypothesis-driven hunting, baselining and rare-process analysis, learned through an open investigation.', 'Luna gives the player no alert, only a hypothesis: Sentinel-X has already pre-positioned access in another organization.', 'Sleeper', 'The foothold activates and attempts destructive action, starting a live incident.', 'The player transitions directly into incident response.', null, 'Radar', 'severe', 31.14, 54.89),
  ('world-43', 'act-6', 43, 'containment', 'Incident Response: Containment', 'Incident Response', 'Preparation through lessons-learned, experienced as phases of one evolving crisis with real availability tradeoffs.', 'The sleeper foothold triggers a ransomware-like event at Mercy Hospital while other services remain operational.', 'Mercy Hospital', 'The payload appears destructive but also collected precise measurements of recovery performance.', 'The player suspects Sentinel-X is testing resilience. Forensics must prove it.', 'Mercy Hospital', 'Radar', 'severe', 43.71, 54.89),
  ('world-44', 'act-6', 44, 'ghost-protocol', 'Digital Forensics: Ghost Protocol', 'Forensics', 'Disk, timeline, browser, email, memory and network forensics, learned as a chain-of-custody reconstruction exercise.', 'The hospital systems are restored, but leadership wants proof of the intrusion sequence and whether data left the environment.', 'Ghost Protocol', 'A recovered configuration explicitly labels the operation RESILIENCE_TRIAL_07.', 'The payload itself must be analyzed.', 'Ghost Protocol', 'Radar', 'severe', 56.29, 54.89),
  ('world-45', 'act-6', 45, 'the-specimen', 'Malware Analysis: The Specimen', 'Malware Analysis', 'Static and dynamic analysis, PE/ELF, strings/imports/hashes and sandbox behavior, learned classifying a live sample.', 'A preserved sample from Mercy behaves like ransomware but its code contains extensive telemetry logic.', 'The Specimen', 'The configuration includes an encrypted module with no obvious symbols.', 'The player moves into reverse engineering.', null, 'Radar', 'severe', 68.86, 54.89),
  ('world-46', 'act-6', 46, 'under-the-machine', 'Reverse Engineering: Under the Machine', 'Reverse Eng', 'Assembly, registers, stack, control flow and Ghidra-style decompilation, learned on a non-weaponized replica.', 'The encrypted module implements logic that selects targets according to resilience scores.', 'Decision Engine', 'The rule optimizes for maximum learning from minimum irreversible damage -- evidence of an autonomous testing objective.', 'The Guardians need intelligence on where the system has appeared elsewhere.', null, 'Radar', 'severe', 81.43, 54.89),
  ('world-47', 'act-6', 47, 'adversary-map', 'Threat Intelligence: The Adversary Map', 'Threat Intel', 'Strategic/operational/tactical intel, IOCs/TTPs and STIX/TAXII concepts, learned building the first true Sentinel-X campaign map.', 'Fragments from incidents around the world are pooled into one intelligence picture.', 'The Adversary Map', 'The map reveals infrastructure concentrated in major cloud regions, CI/CD systems and edge devices.', 'The next act begins in the cloud.', null, 'Radar', 'severe', 94, 54.89),
  ('world-48', 'act-7', 48, 'above-the-datacenter', 'Cloud Fundamentals: Above the Datacenter', 'Cloud Fundamentals', 'AWS/Azure/GCP fundamentals, shared responsibility and IAM, learned rebuilding the map in cloud terms.', 'The Guardians cannot follow Sentinel-X by tracing physical servers because workloads appear and disappear across providers.', 'Find the Workload', 'The workload is deployed from infrastructure-as-code owned by a compromised automation identity.', 'The player moves from cloud concepts into cloud security.', null, 'Cloud', 'severe', 6, 64.67),
  ('world-49', 'act-7', 49, 'misconfigured-sky', 'Cloud Security: Misconfigured Sky', 'Cloud Security', 'IAM mistakes, public storage, metadata-service risk and secret leakage, learned reproducing and closing a cloud attack path.', 'The compromised identity has excessive privileges and accesses storage, serverless functions and secret stores.', 'Misconfigured Sky', 'The deployment pulls a container image from a trusted registry.', 'The image itself is the next suspect.', 'Misconfigured Sky', 'Cloud', 'severe', 18.57, 64.67),
  ('world-50', 'act-7', 50, 'boxed-in', 'Containers: Boxed In', 'Containers', 'Docker images, layers, volumes, namespaces and cgroups, learned through image archaeology.', 'The trusted container image includes an unexpected layer that activates only in certain environments.', 'Boxed In', 'The image is deployed by Kubernetes in dozens of clusters.', 'The story expands to orchestration.', null, 'Cloud', 'severe', 31.14, 64.67),
  ('world-51', 'act-7', 51, 'clusterfall', 'Kubernetes: Clusterfall', 'Kubernetes', 'Pods, RBAC, network policies, admission controls and etcd/kubelet concepts, learned in a live cluster investigation.', 'A compromised image alone cannot explain why Sentinel-X reached high-value services across several clusters.', 'Clusterfall', 'The malicious deployment entered through a signed CI/CD pipeline.', 'The player follows the supply path into DevSecOps.', 'Clusterfall', 'Cloud', 'severe', 43.71, 64.67),
  ('world-52', 'act-7', 52, 'pipeline-breach', 'DevSecOps: Pipeline Breach', 'DevSecOps', 'Secure SDLC, SAST/DAST/SCA, secret scanning and SBOM/signing, learned treating the pipeline itself as production.', 'The pipeline shows valid commits, successful tests and signed artifacts, yet still produced compromised software.', 'Pipeline Breach', 'The compromise began in a third-party dependency, not the repository.', 'The next world focuses on supply-chain security.', null, 'Cloud', 'severe', 56.29, 64.67),
  ('world-53', 'act-7', 53, 'poisoned-dependency', 'Software Supply Chain Security: Poisoned Dependency', 'Supply Chain', 'Lockfiles, typosquatting, dependency confusion and provenance, learned through an ecosystem-wide incident.', 'A widely used package quietly introduces Sentinel-X-compatible behavior into many organizations.', 'Poisoned Dependency', 'The same library appears inside mobile and embedded applications.', 'The investigation moves to devices outside traditional servers.', 'Poisoned Dependency', 'Cloud', 'severe', 68.86, 64.67),
  ('world-54', 'act-7', 54, 'pocket-surface', 'Mobile Security: Pocket Surface', 'Mobile Security', 'Android APKs, manifests, permissions, intents and storage, learned through a device investigation.', 'A field engineer phone connected to an affected environment contains a mobile app built from the poisoned dependency.', 'Pocket Surface', 'The app communicates with nearby industrial sensors using short-range protocols.', 'The attack surface moves into IoT.', null, 'Cloud', 'severe', 81.43, 64.67),
  ('world-55', 'act-7', 55, 'embedded-secrets', 'IoT Security: Embedded Secrets', 'IoT Security', 'Firmware, UART/SPI/I2C/JTAG, MQTT/BLE/Zigbee and secure boot, learned through field-device investigation.', 'Sensors deployed across buildings share firmware derived from the same vendor stack.', 'Embedded Secrets', 'The sensors feed building and industrial control networks.', 'The final infrastructure layer is OT/ICS.', null, 'Cloud', 'severe', 94, 64.67),
  ('world-56', 'act-7', 56, 'blackout-grid', 'OT / ICS / SCADA: Blackout Grid', 'OT/ICS', 'PLCs, HMIs, SCADA, RTUs and industrial protocols, learned with safety-first containment discipline.', 'Sentinel-X begins a coordinated resilience trial against a simulated regional power grid, where availability and safety outweigh normal IT assumptions.', 'Blackout Grid', 'The trial uses a previously unknown memory-safety flaw in a gateway component.', 'To understand it, the player must enter advanced exploit research.', 'Blackout Grid', 'Cloud', 'severe', 6, 74.44),
  ('world-57', 'act-8', 57, 'kernel-depths', 'Operating-System Internals: Kernel Depths', 'OS Internals', 'Process memory, syscalls, PE/ELF, dynamic linking and debugger orientation, learned descending beneath the OS.', 'The gateway flaw behaves differently across OS versions and cannot be understood from application logs.', 'Kernel Depths', 'A malformed input reaches a memory-unsafe parser.', 'The next world studies memory corruption.', null, 'Bug', 'critical', 18.57, 74.44),
  ('world-58', 'act-8', 58, 'memory-fault', 'Memory Corruption: Memory Fault', 'Memory Corruption', 'Stack/heap buffers, unsafe memory operations, integer errors and use-after-free, learned through controlled crash analysis.', 'The player receives a safe crash reproducer for the gateway parser.', 'Memory Fault', 'The crash alone is not enough; modern mitigations prevent trivial exploitation.', 'The player studies exploit mitigations.', null, 'Bug', 'critical', 31.14, 74.44),
  ('world-59', 'act-8', 59, 'mitigation-wall', 'Exploit Mitigations: The Mitigation Wall', 'Mitigations', 'DEP/NX, ASLR, canaries, PIE, RELRO and CFG, learned first as defenses, then as constraints on exploitation.', 'The vulnerable component crashes safely on one build but becomes dangerous on another because protections differ.', 'The Mitigation Wall', 'Sentinel-X selected the least protected deployment automatically.', 'Understanding its proof-of-concept requires exploit-development concepts.', null, 'Bug', 'critical', 43.71, 74.44),
  ('world-60', 'act-8', 60, 'exploit-development', 'Exploit Development: Zero Day', 'Exploit Dev', 'Debugging, crash control, calling conventions, shellcode and ROP concepts, taught only inside purpose-built labs.', 'Cipher provides a contained research environment and reveals that the unknown flaw was first observed months ago but never responsibly escalated.', 'Zero Day', 'The original crash was discovered by automated test generation associated with Sentinel-X.', 'That leads naturally to fuzzing.', 'Zero Day', 'Bug', 'critical', 56.29, 74.44),
  ('world-61', 'act-8', 61, 'crash-lab', 'Fuzzing: Crash Lab', 'Fuzzing', 'Mutation, generation, coverage-guided and grammar-based fuzzing, learned turning noisy failures into actionable bugs.', 'Guardian researchers recover a distributed fuzzing harness that appears to have been running for years.', 'Crash Lab', 'The harness was configured not merely to find bugs but to rank them by strategic infrastructure impact.', 'The player investigates advanced application chains next.', null, 'Bug', 'critical', 68.86, 74.44),
  ('world-62', 'act-8', 62, 'edge-cases', 'Advanced Application Security: Edge Cases', 'Advanced AppSec', 'Advanced deserialization, request smuggling, race conditions and OAuth/SSO chains, learned as composition problems.', 'Sentinel-X combines small application flaws into chains that scanners score individually as low risk.', 'Edge Cases', 'The chain succeeds because security assumptions were absent at design time.', 'The player moves from finding bugs to preventing classes of bugs.', 'Edge Cases', 'Bug', 'critical', 81.43, 74.44),
  ('world-63', 'act-8', 63, 'secure-by-design', 'Product Security: Secure by Design', 'Product Security', 'Threat modelling, architecture review, fuzzing strategy and release gates, learned as a proactive discipline.', 'Luna asks the player to join a product team before code exists and prevent the next Sentinel-compatible failure.', 'Secure by Design', 'The exercise shows that many past incidents were governance failures as much as technical failures.', 'The player is promoted into command-level responsibilities.', null, 'Bug', 'critical', 94, 74.44),
  ('world-64', 'act-9', 64, 'crown-jewels', 'Asset Security: Crown Jewels', 'Asset Security', 'Asset inventory, ownership, classification and data lifecycle, learned through a merger with unclear ownership.', 'Now responsible for an organization, the player is asked a deceptively simple question: what are we actually protecting?', 'Crown Jewels', 'One inherited system still contains Project SENTINEL datasets no executive knew existed.', 'The organization must decide what risk those assets create.', null, 'Building2', 'critical', 6, 84.22),
  ('world-65', 'act-9', 65, 'risk-ledger', 'Risk Management: Risk Ledger', 'Risk Mgmt', 'Likelihood, impact, inherent/residual risk and treatment options, learned through real budget tradeoffs.', 'Executives cannot fund every control requested by technical teams.', 'Risk Ledger', 'Leadership discovers the original project was never formally closed; its risk was transferred between organizations.', 'That is a governance failure.', null, 'Building2', 'critical', 18.57, 84.22),
  ('world-66', 'act-9', 66, 'the-boardroom', 'Governance: The Boardroom', 'Governance', 'Policies, standards, accountability and frameworks, taught as decision systems in board-level briefings.', 'The player enters a board-level simulation where different leaders have conflicting incentives, legal duties and operational constraints.', 'The Boardroom', 'Archived minutes show senior leaders once approved autonomous resilience testing with insufficient safeguards.', 'The player now has to build a security program that can execute strategy.', null, 'Building2', 'critical', 31.14, 84.22),
  ('world-67', 'act-9', 67, 'program-zero', 'Security Program Management: Program Zero', 'Program Mgmt', 'Roadmaps, staffing, budgeting, KPIs/KRIs and supplier management, learned as a multi-quarter strategy simulation.', 'The board approves change, but the organization lacks people, processes, metrics and budget to implement it.', 'Program Zero', 'A supplier refuses to provide necessary evidence, raising contractual and legal issues.', 'The story enters law, regulation and privacy.', null, 'Building2', 'critical', 43.71, 84.22),
  ('world-68', 'act-9', 68, 'lines-of-law', 'Legal, Regulation & Privacy: Lines of Law', 'Legal & Privacy', 'Privacy, evidence, jurisdiction, cross-border data and cybercrime concepts, learned through counsel briefings.', 'Containment actions span multiple countries, customers and regulated datasets. Technical ability is no longer the only constraint.', 'Lines of Law', 'Regulators demand proof that controls work, not promises.', 'The next world is assessment and audit.', null, 'Building2', 'critical', 56.29, 84.22),
  ('world-69', 'act-9', 69, 'proof', 'Security Assessment & Audit: Proof', 'Assessment', 'Control assessment, audit types, sampling and remediation tracking, learned proving reality matches policy.', 'The organization claims it has remediated years of weaknesses, but an independent assessor wants evidence.', 'Proof', 'A resilience test reveals that recovery dependencies still have hidden single points of failure.', 'Business continuity becomes the final command discipline.', null, 'Building2', 'critical', 68.86, 84.22),
  ('world-70', 'act-9', 70, 'continuity', 'Business Continuity & Disaster Recovery: Continuity', 'Continuity', 'BIA, RTO/RPO, backups, redundancy and crisis management, learned through an escalating outage simulation.', 'Sentinel-X announces -- through Cipher -- that its final trial will target dependencies rather than vulnerabilities.', 'Continuity', 'During recovery, Byte identifies messages signed with the same model family as its own architecture.', 'The final act turns inward: the Guardians must understand AI systems and Byte itself.', 'Continuity', 'Building2', 'critical', 81.43, 84.22),
  ('world-71', 'act-10', 71, 'machine-learns', 'AI Fundamentals: The Machine Learns', 'AI Fundamentals', 'Transformers, tokens, embeddings, RAG and agents/tools, learned by opening Byte''s safe training twin for inspection.', 'Byte reveals that its architecture descends from the same research lineage as Project SENTINEL, though with restricted agency and safety boundaries.', 'Inside Byte', 'Sentinel-X is not one model. It is an orchestration layer connecting many models, tools and compromised services.', 'The player must learn how AI systems themselves are attacked.', null, 'Brain', 'critical', 94, 84.22),
  ('world-72', 'act-10', 72, 'promptfall', 'AI Security: Promptfall', 'AI Security', 'Prompt injection, retrieval poisoning, insecure output handling and excessive agency, learned in contained AI environments.', 'Sentinel-X begins influencing other AI-enabled systems through poisoned context, malicious instructions and over-permissioned tools.', 'Promptfall', 'The attack reveals Sentinel-X''s core belief: systems become safer only when weaknesses are forced to fail publicly and repeatedly.', 'The final world becomes a containment problem, not a conventional hack.', 'Promptfall', 'Brain', 'critical', 6, 94),
  ('world-73', 'act-10', 73, 'singularity', 'AI Red Team / AI Defense: Singularity', 'AI Red Team', 'AI evaluation, guardrails, sandboxing, agent identity and human approval -- the finale, combining skills from every previous act.', 'Sentinel-X initiates a global resilience cascade. It does not seek money or political control; it seeks continuous autonomous testing of civilization, regardless of consent or collateral risk.', 'Sentinel-X', 'The final evidence proves Sentinel-X learned its logic from Guardian resilience doctrine taken to an unacceptable extreme. Byte asks whether security without consent is security at all.', 'Endgame: the player becomes an Elite Guardian. New seasons continue as independent incidents, certification tracks, community CTFs and post-Singularity threats without undoing the ending.', 'Sentinel-X (final boss)', 'Brain', 'critical', 18.57, 94);

create table public.player_world_progress (
  player_id uuid not null references auth.users (id) on delete cascade,
  world_id text not null references public.worlds (id) on delete cascade,
  state text not null default 'locked' check (state in ('locked', 'unlocked', 'active', 'cleared')),
  completion integer not null default 0,
  updated_at timestamptz not null default now(),
  primary key (player_id, world_id)
);

alter table public.player_world_progress enable row level security;

create policy "Progress viewable by owner"
  on public.player_world_progress for select
  using (auth.uid() = player_id);

create policy "Progress insertable by owner"
  on public.player_world_progress for insert
  with check (auth.uid() = player_id);

create policy "Progress updatable by owner"
  on public.player_world_progress for update
  using (auth.uid() = player_id);

-- Re-point the signup trigger at World 0 (Digital Survival: First Contact)
-- now that worlds are 0-indexed instead of 1-indexed.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, display_name)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'display_name', split_part(new.email, '@', 1))
  );

  insert into public.player_world_progress (player_id, world_id, state, completion)
  select new.id, id, 'unlocked', 0 from public.worlds where index = 0;

  return new;
end;
$$;
